from argon2 import PasswordHasher
from argon2.exceptions import VerifyMismatchError
import bcrypt

_ph = PasswordHasher()


def hash_pw(pw):
    return _ph.hash(pw)


def check(user, pw):
    stored = user.password_hash
    if stored.startswith('$2b$'):
        # legacy bcrypt hash: verify, then transparently upgrade
        if not bcrypt.checkpw(pw.encode(), stored.encode()):
            return False
        user.password_hash = _ph.hash(pw)
        user.save(update_fields=['password_hash'])
        return True
    try:
        return _ph.verify(stored, pw)
    except VerifyMismatchError:
        return False
